class OpenBESCase(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
    )
    inputs: OpenBESSpecification
    outputs: Optional[OpenBESOutput] = None
    log: Optional[list[str]] = Field(
        default=None, description="Log output from the simulation run."
    )
    meta: Optional[OpenBESMetaData] = None
